import re
import sys

values = {}
pattern = re.compile(
    r"\s*(\w+)\s*<-\s*(?:(\d+)|"
    r"\(\s*(\w+)\s*\+\s*(\d+)\s*\)\s*mod\s*(\d+))\s*;"
)

for line in sys.stdin:
    match = pattern.fullmatch(line)
    if not match:
        continue

    target, literal, source, increment, modulus = match.groups()
    if literal is not None:
        values[target] = int(literal)
    else:
        values[target] = (values[source] + int(increment)) % int(modulus)

print(f"a ?= {values['a']}; b ?= {values['b']}; TMP ?= {values['TMP']};")
